def encode_shift(s: str) -> str:
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([encode_shift_single_char(ch) for ch in s])

def decode_shift(s: str) -> str:
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([decode_shift_single_char(ch) for ch in s])

def encode_shift_single_char(ch: str) -> str:
    """
    Helper function to shift a single character by 5 in the alphabet.
    """
    if ch.islower():
        return chr(((ord(ch) - ord('a') + 5) % 26) + ord('a'))
    elif ch.isupper():
        return chr(((ord(ch) - ord('A') + 5) % 26) + ord('A'))
    else:
        return ch

def decode_shift_single_char(ch: str) -> str:
    """
    Helper function to decode a single character by shifting back by 5 in the alphabet.
    """
    if ch.islower():
        return chr(((ord(ch) - ord('a') - 5) % 26) + ord('a'))
    elif ch.isupper():
        return chr(((ord(ch) - ord('A') - 5) % 26) + ord('A'))
