import math

def sieve_of_eratosthenes(n: int) -> list[int]:
    """Generate a list of prime numbers up to, but not including, n using the Sieve of Eratosthenes."""
    if not isinstance(n, int) or n < 2:
        return []

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for i in range(2, int(math.sqrt(n)) + 1):
        if sieve[i]:
