from collections import defaultdict

def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

    # Check if input is a string
    if not isinstance(test, str):
        return {}

    # Remove spaces and convert to lowercase
    test = test.replace(' ', '').lower()

    # Handle empty string or only spaces
    if not test:
        return {}

    # Count occurrences of each character
    char_count = defaultdict(int)
    for char in test:
        if char.isalpha():  # Ensure only letters are counted
            char_count[char] += 1

    # If no characters were counted (e.g., input was only spaces or special characters)
    if not char_count:
        return {}

    # Determine maximum count
    max_count = max(char_count.values())

    # Collect characters with maximum count
    max_chars = {char: count for char, count in char_count.items() if count == max_count}

    return max_chars

